macro_rules! deps {
    () => {
        Outcome!();
        Resource!();
        Error!();
    };
}

macro_rules! prepare_diff {
    () => {
        deps!();
        # [doc = ""] pub mod prepare_diff { use bstr :: BStr ; use crate :: blob :: platform :: Resource ; # [doc = " The kind of operation that should be performed based on the configuration of the resources involved in the diff."] # [derive (Debug , Copy , Clone , Eq , PartialEq)] pub enum Operation < 'a > { # [doc = " The [internal diff algorithm](imara_diff::diff) should be called with the provided arguments."] # [doc = " This only happens if none of the resources are binary, and if there is no external diff program configured via git-attributes"] # [doc = " *or* [Options::skip_internal_diff_if_external_is_configured](super::Options::skip_internal_diff_if_external_is_configured)"] # [doc = " is `false`."] # [doc = ""] # [doc = " Use [`Outcome::interned_input()`] to easily obtain an interner for use with [`imara_diff::diff()`], or maintain one yourself"] # [doc = " for greater reuse."] InternalDiff { # [doc = " The algorithm we determined should be used, which is one of (in order, first set one wins):"] # [doc = ""] # [doc = " * the driver's override"] # [doc = " * the platforms own configuration (typically from git-config)"] # [doc = " * the default algorithm"] algorithm : imara_diff :: Algorithm , } , # [doc = " Run the external diff program according as configured in the `source`-resources driver."] # [doc = " This only happens if [Options::skip_internal_diff_if_external_is_configured](super::Options::skip_internal_diff_if_external_is_configured)"] # [doc = " was `true`, preventing the usage of the internal diff implementation."] ExternalCommand { # [doc = " The command as extracted from [Driver::command](super::super::Driver::command)."] # [doc = " Use it in [`Platform::prepare_diff_command`](super::Platform::prepare_diff_command()) to easily prepare a compatible invocation."] command : & 'a BStr , } , # [doc = " One of the involved resources, [`old`](Outcome::old) or [`new`](Outcome::new), were binary and thus no diff"] # [doc = " cannot be performed."] SourceOrDestinationIsBinary , } # [doc = " The outcome of a [`prepare_diff`](super::Platform::prepare_diff()) operation."] # [derive (Debug , Copy , Clone , Eq , PartialEq)] pub struct Outcome < 'a > { # [doc = " The kind of diff that was actually performed. This may include skipping the internal diff as well."] pub operation : Operation < 'a > , # [doc = " If `true`, a [binary to text filter](super::super::Driver::binary_to_text_command) was used to obtain the buffer"] # [doc = " of `old` or `new`, making it a derived value."] # [doc = ""] # [doc = " Applications should check for this to avoid treating the buffer content as (original) resource content."] pub old_or_new_is_derived : bool , # [doc = " The old or source of the diff operation."] pub old : Resource < 'a > , # [doc = " The new or destination of the diff operation."] pub new : Resource < 'a > , } impl < 'a > Outcome < 'a > { # [doc = " Produce an instance of an interner which `git` would use to perform diffs."] # [doc = ""] # [doc = " Note that newline separators will be removed to improve diff quality"] # [doc = " at the end of files that didn't have a newline, but had lines added"] # [doc = " past the end."] pub fn interned_input (& self) -> imara_diff :: InternedInput < & 'a [u8] > { imara_diff :: InternedInput :: new (self . old . intern_source_strip_newline_separators () , self . new . intern_source_strip_newline_separators () ,) } } # [doc = " The error returned by [Platform::prepare_diff()](super::Platform::prepare_diff())."] # [derive (Debug , thiserror :: Error)] # [allow (missing_docs)] pub enum Error { # [error ("Either the source or the destination of the diff operation were not set")] SourceOrDestinationUnset , # [error ("Tried to diff resources that are both considered removed")] SourceAndDestinationRemoved , } }
    };
}

prepare_diff!();